const renderPiece = (row, col) => {
  const piece = pieces.find(p => {
    if (p.commonPosition === null) {
      // Pokud má figurka `commonPosition === null`, hledáme její výchozí pozice
      const defaultTiles = Array.from(tileColorMap.entries())
        .filter(([key, color]) => color === p.color) // Vybereme výchozí pozice pro danou barvu
        .map(([key]) => {
          const [r, c] = key.split('-').map(Number);
          return { row: r, col: c };
        });

      // Zkontrolujeme, zda aktuální dlaždice patří k výchozím pozicím
      return defaultTiles.some(pos => pos.row === row && pos.col === col);
    }

    // Pokud má figurka přiřazenou pozici (commonPosition)
    const coords = getCoordinatesFromValue(p.commonPosition, p.color);
    return coords.row === row && coords.col === col;
  });

  if (piece) {
    return (
      <div
        className="piece"
        style={{
          backgroundColor: piece.color || 'gray', 
          border: '2px solid white',
          width: '70%',
          height: '70%',
        }}
      />
    );
  }

  return null; // Pokud na políčku není žádná figurka
};
